package com.kilombino.pyblockwatch.coinjoin

import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Test

/** Real mainnet transactions: Kilojoin rounds are recognised, two equal payments by another wallet are not. */
class MixedCoinsTest {
    // 370b5cc7…: a 3-person Kilojoin round of 25 000 000 sats (block 977056), no change.
    private val round3 = ""
    // 8ced8eed…: a 4-person round of 10 000 000 sats (block 977064), with one change.
    private val round4 = ""
    // b8907260…: two payments of 11 982 sats, each with its own change, signed 0x01.
    private val notRound = ""

    @Test fun kilojoinRoundsAreMixed() {
        for (v in 0 until 3) assertTrue(MixedCoins.looksMixed(round3, v))
        assertTrue((0 until 5).count { MixedCoins.looksMixed(round4, it) } == 4)
    }

    @Test fun equalPaymentsAreNot() {
        for (v in 0 until 4) assertFalse(MixedCoins.looksMixed(notRound, v))
    }
}
